function Stack() {
  this.items = [];
}

Stack.prototype.push = function (x) {
  this.items.push(x);
};

Stack.prototype.pop = function () {
  return this.items.pop();
};

Stack.prototype.peek = function () {
  return this.items[this.items.length - 1];
};

var s = new Stack();
s.push(1);
s.push(2);
s.push(3);
s.pop();
console.log(s.peek());
